 1  import { useEffect, useState } from 'react'
 2  import { mmgisRequest } from './mmgisAPI'
 3  
 4  export const useMMGISToolVars = <
 5      T extends Record<string, unknown> = Record<string, unknown>,
 6  >(
 7      toolName: string,
 8  ): T => {
 9      const [vars, setVars] = useState<T>({} as T)
10      useEffect(() => {
11          let cancelled = false
12          let attempts = 0
13          const MAX = 20 // retry while Layers_.fina() registers the handler (~6s)
14  
15          const tryFetch = () => {
16              if (cancelled || attempts >= MAX) return
17              attempts++
18              mmgisRequest<T>('tool:getVars', toolName)
19                  .then((result) => {
20                      if (cancelled) return
21                      // __noVars (or null) → handler not ready / no saved vars; retry.
22                      if (!result || (result as Record<string, unknown>).__noVars) {
23                          setTimeout(tryFetch, 300)
24                          return
25                      }
26                      setVars(result)
27                  })
28                  .catch((err) => {
29                      if (!cancelled) {
30                          console.warn(`[useMMGISToolVars] '${toolName}' vars unavailable:`, err)
31                          setTimeout(tryFetch, 300)
32                      }
33                  })
34          }
35  
36          tryFetch()
37          return () => {
38              cancelled = true
39          }
40      }, [toolName])
41      return vars
42  }
